<?php
declare(strict_types=1);
require_once __DIR__.'/ImageTaskReconciliationTest.php';
require_once __DIR__.'/ResearchReconciliationTest.php';
use DigiForge\AI\{ImageGenerationJournal,ImageGenerationExecution,ImageGenerationEvidenceStore,MonetaryReservationRepository};
use DigiForge\Research\{ResearchExecutionJournal,ResearchExecution};
final class ExecutionHistoryEvidenceTest extends WP_UnitTestCase {
 use PhotoWorkflowFixtureIsolation {tearDown as private restoreFixture;}
 private array $floors=[];
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();ShopAccessFixture::reset();$this->capturePhotoFixtureState();global $wpdb;foreach(['jobs','ai_models','ai_tasks','integrations','integration_secrets','research_candidates','research_reviews','opportunities','product_families','products','product_versions']as $m){$t=DigiForge\Database\Tables::{$m}();$this->floors[$t]=(int)$wpdb->get_var('SELECT COALESCE(MAX(id),0) FROM '.$t);}wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['personalized_pod'],['manage_digiforge_pod','manage_digiforge_research','manage_digiforge_ai']);DigiForge\Core\Settings::protectProduction();$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');}
 protected function tearDown():void {global $wpdb;foreach(array_reverse($this->floors,true)as $t=>$id)$wpdb->query('DELETE FROM '.$t.' WHERE id>'.(int)$id);$this->restoreFixture();}
 private function checked($v):array {self::assertNotWPError($v,is_wp_error($v)?$v->get_error_code():'');return $v;}
 private function bound(bool $image):array {return (new ReflectionMethod($image?ImageTaskReconciliationTest::class:ResearchReconciliationTest::class,'bound'))->invoke($image?new ImageTaskReconciliationTest():new ResearchReconciliationTest(),false);}
 private function evidence($journal,$job):array|WP_Error {self::assertTrue(method_exists($journal,'executionEvidence'),'Budget consumers require a public verified history projection; private option reconstruction cannot prove absence of dispatch.');return $journal->executionEvidence($job['id'],$job['event_sha256']);}
 /** @dataProvider kinds */
 public function testCancelledUnknownRetainsDispatchHistoryWithoutReleaseAuthority(bool $image):void {
  $f=$this->bound($image);[$s,$j]=$f;$shop='personalized_pod';$cancel=$this->checked($image?$s->cancel($shop,$j['id']):$s->cancel($shop,$j['id'],$j['event_sha256']));$journal=$image?new ImageGenerationJournal():new ResearchExecutionJournal();$before=$this->checked((new MonetaryReservationRepository())->exposure($shop,'USD',$j['identity']['run_context']['run_id']));$writes=[];$http=0;$q=static function($sql)use(&$writes){if(preg_match('/^\s*(INSERT|UPDATE|DELETE|REPLACE)\b/i',$sql))$writes[]=$sql;return $sql;};$h=static function()use(&$http){$http++;return new WP_Error('no_network','Offline only');};add_filter('query',$q);add_filter('pre_http_request',$h);try{$e=$this->checked($this->evidence($journal,$cancel));}finally{remove_filter('query',$q);remove_filter('pre_http_request',$h);}
  self::assertSame([],$writes);self::assertSame(0,$http);self::assertSame('CANCELLED',$e['state']);self::assertTrue($e['dispatch_stage_recorded']);self::assertTrue($e['local_terminal_cancellation']);self::assertFalse($e['reservation_release_authorized']);self::assertFalse($e['execution_fenced']);self::assertFalse($e['cross_root_no_send_verified']);self::assertSame('NOT_ESTABLISHED_BY_EXECUTION_HISTORY',$e['provider_charge_finality']);self::assertSame($cancel['event_sha256'],$e['latest_event_sha256']);self::assertContains('DISPATCHING',array_column($e['events'],'state'));self::assertSame($before,$this->checked((new MonetaryReservationRepository())->exposure($shop,'USD',$j['identity']['run_context']['run_id'])));$hash=$e['sha256'];unset($e['sha256']);self::assertSame($hash,ImageGenerationEvidenceStore::digest($e));$raw=json_encode($e);foreach(['prompt','source_document','b64_json','ciphertext']as $secret)self::assertStringNotContainsString('"'.$secret.'"',$raw);self::assertWPError($journal->executionEvidence($cancel['id'],$j['event_sha256']),'Stale event is not upgraded to current cancellation evidence.');self::assertSame($hash,$this->checked($this->evidence($journal,$cancel))['sha256']);
 }
 /** @dataProvider kinds */
 public function testCostProjectionShowsOnlyObservationsNotReleaseAuthority(bool $image):void {$f=$this->bound($image);$cost=$this->checked($f[0]->costEvidence('personalized_pod',$f[1]['id']));self::assertArrayHasKey('execution_history',$cost);self::assertTrue($cost['execution_history']['dispatch_stage_recorded']);self::assertFalse($cost['execution_history']['reservation_release_authorized']);}
 /** @dataProvider kinds */
 public function testRevocationDuringVerifiedHistoryReadDeniesSnapshot(bool $image):void {$f=$this->bound($image);$j=$f[1];$jr=$image?new ImageGenerationJournal():new ResearchExecutionJournal();$revoked=false;$needle=$image?'digiforge_image_job_event_':'df_s2_research_event_';$q=static function($sql)use(&$revoked,$needle){if(!$revoked&&str_starts_with(ltrim($sql),'SELECT option_value')&&str_contains($sql,$needle)){$revoked=true;wp_get_current_user()->add_cap('manage_digiforge_ai',false);}return $sql;};add_filter('query',$q);try{self::assertWPError($this->evidence($jr,$j));self::assertTrue($revoked);}finally{remove_filter('query',$q);wp_get_current_user()->add_cap('manage_digiforge_ai',true);}}
 /** @dataProvider kinds */
 public function testConcurrentCancellationCannotReturnFormerCurrentSnapshot(bool $image):void {$f=$this->bound($image);[$s,$j]=$f;$jr=$image?new ImageGenerationJournal():new ResearchExecutionJournal();$heads=0;$changed=false;$needle=$image?'digiforge_image_job_head_':'df_s2_research_head_';$q=function($sql)use(&$heads,&$changed,$needle,$s,$j,$image){if(str_starts_with(ltrim($sql),'SELECT option_value')&&str_contains($sql,$needle)&&++$heads===2){$changed=true;$this->checked($image?$s->cancel('personalized_pod',$j['id']):$s->cancel('personalized_pod',$j['id'],$j['event_sha256']));}return $sql;};add_filter('query',$q);try{self::assertWPError($this->evidence($jr,$j));self::assertTrue($changed);}finally{remove_filter('query',$q);}self::assertSame('CANCELLED',$this->checked($jr->read($j['id']))['state']);}
 public function testExtraRunContextCannotLeakPrivateFieldsThroughAnAuthorizedJournal():void {$f=$this->bound(false);$i=$f[1]['identity'];$i['run_context']['source_document']='PRIVATE_SOURCE_NOT_FOR_METADATA_EXPORT';$jr=new ResearchExecutionJournal();$j=$this->checked($jr->create($i,'extra-context-'.wp_generate_uuid4()));self::assertWPError($this->evidence($jr,$j),'Source identity can remain historical, but a metadata export must not copy unrestricted context.');}
 public function testIncompleteAuthorizedJournalCannotProduceInventedRunEvidence():void {$jr=new ResearchExecutionJournal();$j=$this->checked($jr->create(['version'=>'shop2-research-queue-v1','shop_key'=>'personalized_pod','actor_id'=>get_current_user_id(),'mode'=>'NETWORK','sources'=>[str_repeat('a',64)],'contracts'=>[[]]],'missing-run-'.wp_generate_uuid4()));self::assertWPError($this->evidence($jr,$j));}
 public static function kinds():array{return [[true],[false]];}
 public function testNoLocalDispatchRecordStillDoesNotAuthorizeUnusedRelease():void {
  $p=ImagePanelFixture::policy();$spec=ImagePanelFixture::specification();$s=new ImageGenerationExecution();$j=$this->checked($s->prepareDesign('personalized_pod',$spec['hash'],$p['hash'],['run_id'=>'history-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')]));$j=$this->checked($s->cancel('personalized_pod',$j['id']));$e=$this->checked($this->evidence(new ImageGenerationJournal(),$j));self::assertFalse($e['dispatch_stage_recorded']);self::assertFalse($e['reservation_release_authorized']);self::assertFalse($e['cross_root_no_send_verified']);self::assertSame(0,$e['events'][0]['usage_id']);
 }
 public function testForeignActorAndCorruptResearchHistoryCannotExportSourceEvidence():void {
  $f=$this->bound(false);$j=$f[1];$jr=new ResearchExecutionJournal();self::assertTrue(method_exists($jr,'executionEvidence'));global $wpdb;$name='df_s2_research_event_'.$j['id'].'_0';$saved=$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s',$name));$wpdb->update($wpdb->options,['option_value'=>'{}'],['option_name'=>$name]);try{self::assertWPError($jr->executionEvidence($j['id'],$j['event_sha256']));}finally{$wpdb->update($wpdb->options,['option_value'=>$saved],['option_name'=>$name]);}$other=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($other);ShopAccessFixture::authorizeActor($other,['personalized_pod'],['manage_digiforge_pod','manage_digiforge_research','manage_digiforge_ai']);$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');self::assertWPError($jr->executionEvidence($j['id'],$j['event_sha256']));
 }
}
